func TestOpenRejectsPendingHandoverForDestroyedSample(t *testing.T) {
	extra := `,"destroyed":{"operator":"李四","location":"实验室B","at":"2026-10-03T08:00:00Z","reason":"实验结束按规程销毁","qty":6750}`
