// destroyedAt 为销毁类构造数据使用的固定时间。
var destroyedCheckAt = time.Date(2026, 10, 3, 12, 0, 0, 0, time.UTC)

// registerHistoryAt / splitHistoryAt 为构造数据中的既有历史时间。
